package live.linghe.privateinput;
import android.content.*;import java.io.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.json.*;
/** Explicit own-device migration. Uses existing native producer components;
 * all remote/model work runs after legacy queues on SyncTasks.worker. */
final class CloudLearningSync {
 interface Transport{JSONObject post(String path,JSONObject body)throws Exception;}
 private final Context context;private final JSONObject sync,membership,identity;private final Transport transport;private final CloudLearningStore store;private final CloudLearningPolicy policy;private final SharedPreferences prefs;
 private final String group,producer,installation,privacy,owner,endpoint;private final BigInteger epoch,revision;
 CloudLearningSync(Context context,JSONObject sync,Transport transport)throws Exception{
  this.context=context;this.sync=sync;this.transport=transport;store=new CloudLearningStore(context);policy=CloudLearningPolicy.get(context);prefs=context.getSharedPreferences("sync-consent",0);membership=sync.getJSONObject("membership");identity=sync.getJSONObject("identity");group=SyncCrypto.id(membership.getString("group"));endpoint=sync.getString("endpoint");epoch=SyncCrypto.u(membership,"epoch");revision=SyncCrypto.u(membership,"revision");privacy=PersonalReset.generation(context);producer=PersonalLexicon.uuid(new LearningCoordinator(context.getFilesDir(),new File(context.getFilesDir(),"Shared")).replica());installation=store.installation();owner=LearningDeltaIndex.hash(group+"/"+producer+"/"+endpoint+"/"+privacy);
 }
 private void allowed(boolean publication)throws Exception{SyncCrypto.require(privacy.equals(PersonalReset.generation(context))&&(SyncCrypto.find(membership,identity.getString("device")).getInt("permissions")&1)!=0&&group.equals(SyncCrypto.id(sync.getJSONObject("membership").getString("group")))&&epoch.equals(SyncCrypto.u(sync.getJSONObject("membership"),"epoch"))&&revision.equals(SyncCrypto.u(sync.getJSONObject("membership"),"revision")));if(publication)SyncCrypto.require(prefs.getBoolean("learning",false)&&prefs.getBoolean(CloudLearningStore.ENABLED,false)&&!prefs.getBoolean(CloudLearningStore.REVOKE,false));}
 private JSONObject call(int operation,JSONObject body,boolean publication)throws Exception{
  allowed(publication);byte[] encoded=CloudLearningCanonical.encode(body).getBytes(StandardCharsets.UTF_8);if(operation<1||operation>9||encoded.length>524288)throw new IOException("cloud request bound");String nonce=SyncCrypto.id();long now=System.currentTimeMillis()/1000;ByteArrayOutputStream canonical=new ByteArrayOutputStream();DataOutputStream data=new DataOutputStream(canonical);data.write("PrivateInput/cloud-learning-request/v1\0".getBytes(StandardCharsets.UTF_8));data.writeByte(1);data.write(RecentLearningWire.uuid(group));data.write(RecentLearningWire.uuid(identity.getString("device")));data.write(RecentLearningWire.uuid(nonce));RecentLearningWire.number(data,BigInteger.valueOf(now));data.writeByte(operation);data.write(MessageDigest.getInstance("SHA-256").digest(encoded));JSONObject request=new JSONObject().put("version",1).put("group",group).put("sender",identity.getString("device")).put("nonce",nonce).put("issuedAt",now).put("operation",operation).put("body",SyncCrypto.b64(encoded)).put("signature",SyncCrypto.b64(SyncCrypto.sign(canonical.toByteArray(),SyncCrypto.privateKey("Ed25519",identity.getString("signing")))));
  JSONObject response=transport.post("/v1/learning/rpc",request);allowed(publication);SyncCrypto.require(SyncCrypto.u(response,"version").equals(BigInteger.ONE)&&response.getInt("operation")==operation);return response.getJSONObject("result");
 }
 private JSONObject status()throws Exception{JSONObject status=call(1,new JSONObject(),false);if(!CloudLearningState.ALGORITHM.equals(status.getString("algorithm_version")))throw new IOException("cloud algorithm unsupported");SyncCrypto.u(status,"generation");SyncCrypto.u(status,"policy_version");SyncCrypto.u(status,"model_version");if(!(status.get("enabled") instanceof Boolean))throw new IOException("cloud status shape");return status;}
 void configure(boolean enabled,boolean authorizeRank)throws Exception{
  if(!enabled){prefs.edit().putBoolean(CloudLearningStore.ENABLED,false).putBoolean(CloudLearningStore.RANK,false).putBoolean(CloudLearningStore.VALID,false).putBoolean(CloudLearningStore.REVOKE,true).commit();PersonalChangeSignal.notifyChanged(context);drainRevoke();return;}
  SyncCrypto.require(prefs.getBoolean("learning",false));JSONObject status=status();if(!status.getBoolean("enabled")){SyncCrypto.require(SyncCrypto.find(membership,identity.getString("device")).getInt("permissions")==3);try{status=call(2,new JSONObject().put("expected_version",status.get("policy_version")).put("enabled",true),false);}catch(SyncClient.HTTPFailure raced){if(raced.status!=409)throw raced;status=status();if(!status.getBoolean("enabled"))throw raced;}}
  JSONObject consent=status.optJSONObject("consent");if(consent==null||!consent.optBoolean("enabled")||!installation.equals(PersonalLexicon.uuid(consent.getString("installation_id"))))status=call(3,new JSONObject().put("expected_version",consent==null?0:consent.get("version")).put("enabled",true).put("installation_id",installation),false);
  validateStatus(status);prefs.edit().putBoolean(CloudLearningStore.ENABLED,true).putBoolean(CloudLearningStore.RANK,authorizeRank).putBoolean(CloudLearningStore.VALID,false).putBoolean(CloudLearningStore.REVOKE,false).commit();synchronize(true);
 }
 private void validateStatus(JSONObject status)throws Exception{JSONObject consent=status.optJSONObject("consent");if(!status.getBoolean("enabled")||consent==null||!consent.getBoolean("enabled")||!installation.equals(PersonalLexicon.uuid(consent.getString("installation_id")))||SyncCrypto.u(status,"generation").signum()<=0||SyncCrypto.u(consent,"version").signum()<=0)throw new IOException("cloud consent inactive");}
 private void drainRevoke()throws Exception{if(!prefs.getBoolean(CloudLearningStore.REVOKE,false))return;JSONObject status=status(),consent=status.optJSONObject("consent");if(consent!=null&&consent.optBoolean("enabled"))call(3,new JSONObject().put("expected_version",consent.get("version")).put("enabled",false).put("installation_id",consent.getString("installation_id")),false);prefs.edit().putBoolean(CloudLearningStore.REVOKE,false).commit();store.invalidateRank();}
 private CloudLearningState state(JSONObject status)throws Exception{
  BigInteger generation=SyncCrypto.u(status,"generation"),consent=SyncCrypto.u(status.getJSONObject("consent"),"version");JSONObject old=store.read();CloudLearningState current;
  if(old==null||!owner.equals(old.optString("owner"))||!generation.equals(SyncCrypto.u(old,"generation"))){store.invalidateRank();current=CloudLearningState.fresh(owner,producer,installation,generation,consent);}
  else{current=new CloudLearningState(old);current.validate(policy);if(!producer.equals(old.getString("producer")))throw new IOException("cloud state owner");if(!consent.equals(SyncCrypto.u(old,"consent"))||!installation.equals(old.getString("installation"))){store.invalidateRank();current.value.put("consent",consent).put("installation",installation).put("recovered",false).put("ready",false);}}
  if(current.capacityProfile()!=LearningCapacityProfiles.EXPANDED_10000){current.upgradeCapacity(policy);store.write(current.value);}
  return current;
 }
 void synchronize(boolean explicit)throws Exception{
  if(prefs.getBoolean(CloudLearningStore.REVOKE,false)){drainRevoke();return;}if(!prefs.getBoolean(CloudLearningStore.ENABLED,false))return;
  RecentLearningStore.Usage now=RecentLearningStore.usage(context);RecentLearningExchangeState budget=new RecentLearningExchangeState(owner+"/"+epoch);String bound=prefs.getString("cloud-cadence-scope","");if(budget.binding.equals(bound)){budget.attemptMs=prefs.getLong("cloud-cadence-attempt",-1);budget.attemptBoot=prefs.getString("cloud-cadence-boot","");budget.successMs=prefs.getLong("cloud-cadence-success",-1);budget.successBoot=prefs.getString("cloud-cadence-success-boot","");budget.attemptSucceeded=prefs.getBoolean("cloud-cadence-succeeded",false);}if(!budget.due(Math.round(now.uptime*1000),now.bootSession,explicit))return;budget.attempted(Math.round(now.uptime*1000),now.bootSession);saveBudget(budget);
  try{
   JSONObject status=status();try{validateStatus(status);}catch(Exception inactive){store.invalidateRank();throw inactive;}allowed(true);CloudLearningState state=state(status);
   if(!state.value.optBoolean("recovered")){JSONObject body=new JSONObject().put("generation",state.value.get("generation")).put("consent_version",state.value.get("consent")).put("installation_id",installation).put("producer_id",producer);CloudLearningState recovered=state.copy();recovered.recover(call(7,body,true),policy);store.write(recovered.value);state=recovered;}
   LearningCoordinator coordinator=new LearningCoordinator(context.getFilesDir(),new File(context.getFilesDir(),"Shared"));if(coordinator.requiresPrivateRecovery())return;LearningModel source=new LearningModel(LearningCapacityProfiles.EXPANDED_10000);source.merge(coordinator.legacySnapshot());List<LearningModel.Entry> local=source.entries();JSONObject projected=CloudLearningState.project(local,producer,policy,state.value.getJSONObject("accepted"));int limit=explicit?40:4;
   for(int i=0;i<limit;i++){CloudLearningState prepared=state.copy();JSONObject pending=prepared.prepare(projected);store.write(prepared.value);state=prepared;if(pending==null)break;JSONObject receipt=call(6,pending,true);CloudLearningState accepted=state.copy();accepted.receive(receipt);store.write(accepted.value);state=accepted;}
   // Mark complete only after all current own components are acknowledged.
   CloudLearningState checked=state.copy();JSONObject remaining=checked.prepare(projected);store.write(checked.value);state=checked;
   for(int page=0;page<8;page++){JSONObject body=new JSONObject().put("generation",state.value.get("generation")).put("from_version",state.value.get("modelVersion")).put("limit",8);JSONObject delta=call(5,body,true);CloudLearningState staged=state.copy();staged.stage(delta,policy);store.write(staged.value);state=staged;if(!delta.getBoolean("has_more"))break;}
   try{personal(state);}catch(SyncClient.HTTPFailure unsupported){if(unsupported.status!=400&&unsupported.status!=404)throw unsupported;/* Server without personal records: legacy lanes still carry them. */}
   allowed(true);store.publishRank(state,group,epoch,producer);RecentLearningStore.Usage end=RecentLearningStore.usage(context);budget.succeeded(Math.round(end.uptime*1000),end.bootSession);saveBudget(budget);prefs.edit().remove("cloud-learning-last-error").commit();
  }catch(Exception failed){if(failed instanceof SyncClient.HTTPFailure&&(((SyncClient.HTTPFailure)failed).status==403||((SyncClient.HTTPFailure)failed).status==409))store.invalidateRank();prefs.edit().putString("cloud-learning-last-error",failed.getClass().getSimpleName()).commit();throw failed;}
 }
 void authorizeRank()throws Exception{allowed(true);JSONObject verified=status();validateStatus(verified);JSONObject current=store.read();if(current!=null)new CloudLearningState(current).validate(policy);if(current!=null&&(!SyncCrypto.u(current,"generation").equals(SyncCrypto.u(verified,"generation"))||!SyncCrypto.u(current,"consent").equals(SyncCrypto.u(verified.getJSONObject("consent"),"version"))))throw new IOException("cloud rank consent changed");if(current==null||!current.optBoolean("ready")||!current.optBoolean("shadowVerified"))throw new IOException("cloud shadow not reconciled");prefs.edit().putBoolean(CloudLearningStore.RANK,true).commit();store.publishRank(new CloudLearningState(current),group,epoch,producer);}
 private void saveBudget(RecentLearningExchangeState state){prefs.edit().putString("cloud-cadence-scope",state.binding).putLong("cloud-cadence-attempt",state.attemptMs).putString("cloud-cadence-boot",state.attemptBoot).putLong("cloud-cadence-success",state.successMs).putString("cloud-cadence-success-boot",state.successBoot).putBoolean("cloud-cadence-succeeded",state.attemptSucceeded).commit();}
 /** P5: personal word/phrase records use the cloud service as the single authority.
  * Pull first (CRDT merge, never overwrites a newer local record), then upload only
  * records whose content changed since the server last acknowledged them. */
 private void personal(CloudLearningState state)throws Exception{
  File file=new File(context.getFilesDir(),"personal-cloud-v1.json");String scope=owner+"/"+state.value.get("generation")+"/"+state.value.get("consent");
  JSONObject saved=null;try{if(file.isFile())saved=LosslessJson.object(AppFiles.read(file,4*1024*1024),4*1024*1024);}catch(Exception damaged){saved=null;}
  if(saved==null||!scope.equals(saved.optString("scope")))saved=new JSONObject().put("version",1).put("scope",scope).put("pulled",0).put("acked",new JSONObject());
  JSONObject acked=saved.getJSONObject("acked");BigInteger after=SyncCrypto.u(saved,"pulled");PersonalLexicon lexicon=new PersonalLexicon(new File(context.getFilesDir(),"Shared"));boolean changed=false;
  JSONObject base=new JSONObject().put("generation",state.value.get("generation")).put("consent_version",state.value.get("consent")).put("installation_id",installation);
  for(int page=0;page<16;page++){
   JSONObject pulled=call(9,new JSONObject(base.toString()).put("after_version",after).put("limit",256),true);JSONArray rows=pulled.getJSONArray("records");JSONObject incoming=new JSONObject();
   for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id=PersonalLexicon.uuid(row.getString("id"));row.remove("id");incoming.put(id,row);acked.put(id,personalDigest(row));}
   if(incoming.length()>0){lexicon.mergeSynchronized(new JSONObject().put("version",1).put("records",incoming).toString());changed=true;}
   after=SyncCrypto.u(pulled,"next_version");saved.put("pulled",after);if(!pulled.getBoolean("has_more"))break;
  }
  JSONObject local=LosslessJson.object(lexicon.synchronizationSnapshot(),PersonalLexicon.MAX_BYTES*8).getJSONObject("records");JSONArray pending=new JSONArray();Iterator<String> ids=local.keys();
  while(ids.hasNext()){String id=ids.next();JSONObject row=local.getJSONObject(id);String digest=personalDigest(row);if(digest.equals(acked.optString(id)))continue;pending.put(new JSONObject(row.toString()).put("id",id));
   if(pending.length()==256){personalUpload(base,pending,acked);pending=new JSONArray();}}
  if(pending.length()>0)personalUpload(base,pending,acked);
  AppFiles.write(new android.util.AtomicFile(file),saved.toString(),4*1024*1024);if(changed)PersonalChangeSignal.notifyChanged(context);
 }
 private void personalUpload(JSONObject base,JSONArray rows,JSONObject acked)throws Exception{
  JSONObject result=call(8,new JSONObject(base.toString()).put("records",rows),true);SyncCrypto.require(result.getBoolean("accepted"));
  for(int i=0;i<rows.length();i++){JSONObject row=new JSONObject(rows.getJSONObject(i).toString());String id=PersonalLexicon.uuid((String)row.remove("id"));acked.put(id,personalDigest(row));}
 }
 static String personalDigest(JSONObject record)throws Exception{return SyncCrypto.b64(SyncCrypto.sha(SyncCrypto.bytes(LosslessJson.canonical(record))));}

}
